function countTriangles(sticks: number[]): number {
  const n = sticks.length;
  let count = 0;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      for (let k = j + 1; k < n; k++) {
        const a = sticks[i], b = sticks[j], c = sticks[k];
        if (a + b > c && a + c > b && b + c > a) count++;
      }
  return count;
}

