function countTriangles(sticks: number[]): number {
  const s = sticks.slice().sort((a, b) => a - b);
  const n = s.length;
  let count = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const limit = s[i] + s[j];
      let lo = j + 1, hi = n; // first index with s[idx] >= limit
      while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (s[mid] < limit) lo = mid + 1;
        else hi = mid;
      }
      count += lo - (j + 1);
    }
  }
  return count;
}

