function countTriangles(sticks: number[]): number {
  const s = sticks.slice().sort((a, b) => a - b);
  let count = 0;
  for (let k = s.length - 1; k >= 2; k--) {
    let lo = 0, hi = k - 1;
    while (lo < hi) {
      if (s[lo] + s[hi] > s[k]) {
        count += hi - lo;
        hi--;
      } else {
        lo++;
      }
    }
  }
  return count;
}

